/**
 * @file RecommendationFeed.jsx
 * @description Neo-Brutalist AI-recommended prioritized action items generated by LangGraph reasoning.
 * @author Sargam Banerjee (Member 4)
 */

import React from 'react';
import { Zap, MessageSquare, FolderPlus } from 'lucide-react';

export default function RecommendationFeed({ recommendations = [] }) {
  const iconByCategory = {
    skill: <Zap className="w-4 h-4 text-black stroke-[2.5]" />,
    interview: <MessageSquare className="w-4 h-4 text-black stroke-[2.5]" />,
    evidence: <FolderPlus className="w-4 h-4 text-black stroke-[2.5]" />
  };

  const badgeByPriority = {
    high: 'bg-[#FF70A6] text-black border border-black',
    medium: 'bg-[#FFE600] text-black border border-black',
    low: 'bg-[#70E000] text-black border border-black'
  };

  const defaultRecs = [
    {
      id: 1,
      title: 'Close Docker & Containerization Gap',
      priority: 'high',
      category: 'skill',
      description: 'Docker is required by 82% of target Full-Stack listings. Build and containerize a microservice.'
    },
    {
      id: 2,
      title: 'Mock Interview: System Design Patterns',
      priority: 'medium',
      category: 'interview',
      description: 'Practice URL shortener and cache architecture rubric questions before upcoming drives.'
    },
    {
      id: 3,
      title: 'Sync GitHub Commit History',
      priority: 'low',
      category: 'evidence',
      description: 'Run Evidence Agent against recent repos to trigger automated skill verification.'
    }
  ];

  const activeRecs = recommendations && recommendations.length > 0 ? recommendations : defaultRecs;

  return (
    <div className="space-y-3 font-mono">
      {activeRecs.map((rec) => (
        <div
          key={rec.id}
          className="p-3.5 border-2 border-black bg-white shadow-[3px_3px_0px_0px_#000] hover:-translate-y-0.5 hover:shadow-[4px_4px_0px_0px_#000] transition-all flex items-start justify-between gap-3"
        >
          <div className="flex items-start space-x-3">
            <div className="p-2 border border-black bg-[#FAF5E6] flex-shrink-0 mt-0.5 shadow-[1px_1px_0px_0px_#000]">
              {iconByCategory[rec.category] || <Zap className="w-4 h-4 text-black stroke-[2.5]" />}
            </div>
            <div>
              <div className="flex items-center space-x-2">
                <span className="text-xs font-black text-black">{rec.title}</span>
                <span
                  className={`text-[9px] font-black uppercase px-1.5 py-0.2 shadow-[1px_1px_0px_0px_#000] ${badgeByPriority[rec.priority]}`}
                >
                  {rec.priority}
                </span>
              </div>
              <p className="text-[11px] font-bold text-slate-700 mt-1 leading-snug">
                {rec.description}
              </p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}
